Assume that $\mathbb{E}[W\log W]<\log b$ and $\mathbb{E}[W^t]<\infty$ for all $t>0$.   Then $0< D_F<1$ and  almost surely on $\{\mu_\infty\ne 0\}$,  we have 
\[
\dim_{F}(\mu_\infty)  = D_F.
\]

Assume that $\mathbb{E}[W\log W]<\log b$ and $\mathbb{E}[W^t]<\infty$ for all $t>0$.  Then almost surely on $\{\mu_\infty\ne 0\}$,   $\mu_\infty$ is Salem if and only if $W$ has a two-point distribution : 
\begin{align}
\mathbb{P}(W= x^{-1})= 1 - \mathbb{P}(W=0) = x \quad \text{\,with\,} \quad  b^{-1}<x\le 1.
\end{align}

For the   log-normal random weights $W=e^{\sigma N-\sigma^2/2}$ with $0< \sigma < \sqrt{2 \log b}$,  we have 
 \[
 \dim_F(\mu_\infty)  =  \left\{
 \begin{array}{ll}
  \displaystyle 1-  \sigma^2/\log b  & \text{if $ \displaystyle \frac{\sigma^2}{\log b} \le  \frac{1}{2}$}
  \\  
    \displaystyle     1-  \sigma^2/\log b  +     \big( 1 -  \sigma \sqrt{2/\log b} \big)^2 & \text{if $ \displaystyle \frac{1}{2} <   \frac{\sigma^2}{\log b} <  2$}
 \end{array}
 \right.. 
 \]
 }

Suppose that $W$ is in the  squared sub-critical regime. 
Let $0\le \alpha<1$, $1< p\le 2$ and $q> \max\{2, \frac{1}{1 - \alpha}\}$.   Then the following equivalence holds:
\[
\mathcal{N}^{(\alpha, p, q)}(\mu_\infty)<\infty \Longleftrightarrow 
 \mathbb{E}[W^2] < b^{1- 2\alpha- \frac{2}{q}}. 
\]
In particular,  $\mathcal{N}^{(\alpha, p, q)}(\mu_\infty)<\infty$ implies $\alpha<\frac{1}{2}$ and  $q> \frac{2}{1- 2\alpha}$.

Suppose that $W$ is in  the squared critical regime. Let $0\le \alpha<\frac{1}{2}$. Then in the range $1< p\le 2 < q <\infty$ and $q> \frac{2}{1 - 2 \alpha}$, the condition $ \mathbb{E}[W^2] < b^{1- 2\alpha- \frac{2}{q}}$ implies that $\mathcal{N}^{(\alpha, p, q)}(\mu_\infty)<\infty$.

Let $0\le \alpha<\frac{1}{2}$ and $q>\frac{2}{1-2\alpha}$. Assume that $\frac{1}{2}<\beta<1$.   Then the following assertions are equivalent:
\begin{itemize}
\item[(A1).]$\mathcal{N}^{(\alpha, p, q)}(\mu_\infty)<\infty$ holds for all $p$ with $1< p< \frac{1}{\beta}$; 
\item[(A2).] $\mathcal{N}^{(\alpha, p, q)}(\mu_\infty)<\infty$ holds for all $p$ with $\frac{2}{3\beta}< p< \frac{1}{\beta}$; 
\item[(A3).]  $\mathcal{N}^{(\alpha, p, q)}(\mu_\infty)<\infty$ holds for some $p$ with $\frac{2}{3\beta}<p< \frac{1}{\beta}$; 
\item[(A4).] $\alpha +q^{-1}  \le    \frac{\psi(\beta)}{\log b}$.
\end{itemize}

Assume that $1<p<2\le q<\infty$.   Let  $\mathcal{V}: \mathfrak{B}^b\rightarrow \ell^q$ be a vector measure. Suppose that $\mathbb{E}[W^q]<\infty$.  Then
\begin{multline*}
\|\mathcal{V}([0,1])\|_{\ell^q}^p +    \|\mathring{W}\|_1^p\cdot    \chi(\mathcal{V}, W, p, q)   
\\
\lesssim_{p,q}\sup_{n\ge 1} \mathbb{E} \Big[ \big  \| Q_n\mathcal{V}([0,1])\big\|_{\ell^q}^p \Big]  \lesssim_{p,q} 
\\
  \lesssim_{p,q}    \|\mathcal{V}([0,1]) \|_{\ell^q}^p +     \|\mathring{W}\|_q^{p}
 \cdot  \chi(\mathcal{V}, W, p, q). 
\end{multline*}  
In particular, the martingale $(Q_n\mathcal{V}([0,1]))_{n\ge 1}$ is uniformly  bounded in $L^p(\ell^q)$  if and only if the characteristic quantity $\chi(\mathcal{V}, W, p, q)<\infty$.

Let $0\le \alpha<1$.  Assume that $1< p\le 2 \le q <\infty$ and $q> \frac{1}{1 - \alpha}$.  Assume moreover that $\mathbb{E}[W^q]<\infty$. Then there exist two constants $c_1, c_2>0$ depending on $b, \alpha, p, q$ such that 
\begin{align*}
c_1  \cdot   \frac{\|\mathring{W}\|_1}{\|W\|_2}  \cdot  \big\|\mathcal{R}\big\|_{\ell^{\frac{p}{q}}}^{\frac{1}{p}}
 \le   \mathcal{N}^{(\alpha, p, q)}(\mu_\infty) 
\le c_2  \cdot  \|\mathring{W}\|_q     \cdot \big\|\mathcal{R}\big\|_{\ell^1}^{\frac{1}{p}}.
\end{align*}

Assume that $\mathbb{X}$ is a  Banach space   with martingale type  $p \in (1,2]$.  Then there exists a constant $C = C(p, \mathbb{X})$ such that for any  vector measure $\mathcal{V}: \mathfrak{B}^b \rightarrow \mathbb{X}$, 
\begin{align}
\sup_{n\ge 1} \mathbb{E}\big[\big\|Q_n\mathcal{V}([0,1])\big\|_{\mathbb{X}}^p\big] \le      C   \sum_{n\ge 0} \Big( \frac{\mathbb{E}[W^p]}{b^{p-1}}\Big)^n  \cdot    
\|T_n^\mathcal{V}\|_{L^p(\mathbb{X})}^p.
\end{align}

Let $\nu$ be a  Borel probability measure on $[0,1]$.  Assume that there exist $\kappa\in (0,1]$ and $c>0$ such that 
\begin{align}
|\widehat{\nu}(l)|\le  \frac{c}{|l|^{\kappa}} \quad \text{for all $l\in \mathbb{Z}^* = \mathbb{Z}\setminus \{0\}$}.
\end{align}
Then there exists $c'>0$ such that
\begin{align}
\sup_{\text{$I \subset[0,1]$: sub-intervals}}\Big|\int_{I}e^{-i 2\pi l t}\nu(dt)\Big| \le c' \cdot \frac{\log l}{l^{\kappa}} \quad \text{for all $l>1$}. 
\end{align}
